 "content": "from collections import Counter


def transform(grid):
    """Decode the raster enclosed by the rare-color lattice intersections."""
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    ordinary_colors = {value for value, _ in counts.most_common(2)}
    marker_colors = set(counts) - ordinary_colors

    marker_rows = [r for r, row in enumerate(grid)
                   if any(value in marker_colors for value in row)]
    marker_cols = [c for c in range(len(grid[0]))
                   if any(grid[r][c] in marker_colors for r in range(len(grid)))]

    output = []
    for r0, r1 in zip(marker_rows, marker_rows[1:]):
        out_row = []
        for c0, c1 in zip(marker_cols, marker_cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1],
                       grid[r1][c0], grid[r1][c1])
            if corners[0] in marker_colors and all(v == corners[0] for v in corners):
                out_row.append(corners[0])
            else:
                out_row.append(background)
        output.append(out_row)
    return output


if __name__ == "__main__":
    # Build the current test lattice in its repeated 5x4 cell pattern.
    marker_rows = {
        1: [4, 4, 6, 6, 6], 5: [4, 4, 6, 6, 6],
        9: [6, 6, 7, 7, 7], 13: [6, 6, 4, 4, 7],
        17: [4, 4, 4, 4, 7], 21: [4, 4, 7, 6, 6],
        25: [7, 7, 7, 6, 6],
    }
    grid = []
    for r in range(27):
        if r in marker_rows:
            row = [7] * 22
            for c, color in zip((0, 5, 10, 15, 20), marker_rows[r]):
                row[c] = color
        else:
            row = [7 if c % 5 == 0 else 3 for c in range(22)]
        grid.append(row)
    result = transform(grid)
    print(result)
    assert result == [
        [4, 3, 6, 6], [6, 3, 3, 3], [3, 3, 4, 3],
        [3, 3, 4, 3], [4, 3, 3, 3], [3, 3, 3, 6]
    ]
    print("test passed")
